private static boolean endsWith(String str, String suffix, boolean ignoreCase) {
   // <p>Check if a String ends with a specified suffix (optionally case insensitive).</p>
   // @see String#endsWith(String)
   // @param str the String to check, may be null
   // @param suffix the suffix to find, may be null
   // @param ignoreCase indicates whether the compare should ignore case(case insensitive) or not.
   // @return true if the String starts with the prefix or both null

   // check if str or suffix is null
   if (str == null || suffix == null) {
       if (ignoreCase) {
           // check if suffix is null
           if (suffix == null) {
               return false;
           }
           // check if str is null
           return str == null;
       }
       // check if str and suffix are equal
       return str.equals(suffix);
   }

   // if ignoreCase is false, check if str and suffix are equal while ignoring case
   if (!ignoreCase) {
       return str.equalsIgnoreCase(suffix);
   }

   // check if suffix.length() is greater than str.length()
   if (suffix.length() > str.length()) {
       return false;
   }

   // check if str ends with suffix
   return str.endsWith(suffix);
}

