   // check if both str and prefix are null
   if (str == null && prefix == null) {
      return true;
   // handle null str
   } else if (str == null) {
      return false;
   // handle null prefix
   } else if (prefix == null) {
      return false;
   }
   // get the length of str and prefix
   int lengthStr = str.length();
   int lengthPrefix = prefix.length();
   // check if length of str is longer than length of prefix
   if (lengthStr < lengthPrefix) {
      return false;
   }
   // compare the strings, optionally case-insensitive
   if (ignoreCase) {
      return str.regionMatches(ignoreCase, 0, prefix, 0, lengthPrefix);
   } else {
      return str.startsWith(prefix, 0);
   }
}

