public static void generateCompleteBipartiteGraph(Graph<V,E> target, Map<String,V> resultMap) {
    int numVertices = resultMap.size();
    int numEdges = numVertices * (numVertices - 1) / 2;
    int size = Math.max(numVertices, numEdges);

    target.reset();
    target.addVertices(size);
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            if (i != j && !resultMap.containsKey(i + "_" + j)) {
                E edge = target.constructEdge(resultMap.get(i), resultMap.get(j));
                target.addEdge(edge);
            }
        }
    }
    target.finalize();
}

