    List<Integer> lowerBounds = new ArrayList<Integer>();
    Map<K, Integer> upperBounds = new HashMap<K, Integer>();

    for (K key : keys) {
        int lowerBound = key.hashCode();
        int upperBound = key.hashCode();

        for (Map.Entry<K, Integer> entry : upperBounds.entrySet()) {
            K otherKey = entry.getKey();
            int otherValue = entry.getValue();

            if (key.equals(otherKey)) {
