    }

    // Remove leading slashes from relative path
    while (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split path and relative path into lists of folders
    List<String> pathFolders = Arrays.asList(path.split("/"));
    List<String> relativePathFolders = Arrays.asList(relativePath.split("/"));

    // Iterate through the relative path folders
    for (String folder : relativePathFolders) {
        // If the folder is ".", move up one level
        if (folder.equals(".")) {
            if (pathFolders.size() > 0) {
                pathFolders.remove(pathFolders.size() - 1);
            }
        // If the folder is "..", move up two levels
        } else if (folder.equals("..")) {
            if (pathFolders.size() > 1) {
                pathFolders.remove(pathFolders.size() - 1);
                pathFolders.remove(pathFolders.size() - 1);
            }
        // Otherwise, add the folder to the path
        } else {
            pathFolders.add(folder);
        }
    }

    // Join the path folders with the correct separator
    String separator = Paths.get(path).getFileSystem().getSeparator();
    String appliedPath = String.join(separator, pathFolders);

    // Add trailing slash to path if needed
    if (path.endsWith("/") && !appliedPath.endsWith("/")) {
        appliedPath += separator;
    }

