    // Initialize a counter to keep track of the number of nodes removed
    int removedNodes = 0;

    // Traverse the Category tree in a depth-first manner
    for (Category category : categories) {
        if (category.getChildren().isEmpty()) {
            // If the current category has no children, check if it is inactive
            if (!category.isActive()) {
                // If the category is inactive, remove it from the tree
                removedNodes++;
                categories.remove(category);
            }
        } else {
            // If the current category has children, recursively remove any inactive nodes from its subtree
            removedNodes += category.removeUnusedNodes();
        }
    }

    return removedNodes;
}

