            return 0;
        } else if (aArr1.length == 0) {
            return -1;
        } else {
            return 1;
        }
    }

    // Compare the arrays lexicographically
    for (int i = 0; i < Math.min(aArr1.length, aArr2.length); i++) {
        if (aArr1[i] < aArr2[i]) {
            return -1;
        } else if (aArr1[i] > aArr2[i]) {
            return 1;
        }
    }

    // If one array is a prefix of the other, the shorter array is less
