public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAncodeAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> snapshots = new ArrayList<>();

	// Check if the file is valid
	if (!file.exists() || !file.canRead()) {
		throw new FileNotFoundException(file.getPath() + " does not exist or cannot be read");
	}

	// Check if the timeRanges are valid
	if (timeRanges.isEmpty()) {
		throw new IOException("No time ranges provided");
	}

	// Parse the file
	BufferedReader reader = new BufferedReader(new FileReader(file));
	String line;
	while ((line = reader.readLine()) != null) {
		// Parse the line
		String[] parts = line.split(",");

		// Check if the line contains a thread snapshot
		if (parts.length < 2) {
			continue;
		}

		// Get the time range
		long timestamp = Long.parseLong(parts[0]);
		timeRange.add(timestamp);

		// Check if the timestamp is within the allowed time range
		boolean inRange = false;
		for (ProfileAncodeAnalyzeTimeRange range : timeRanges) {
			if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
				inRange = true;
				break;
			}
		}

		// Add the snapshot to the list
		if (inRange) {
			snapshots.add(new ThreadSnapshot(file, timestamp));
		}
	}

	reader.close();

	return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            if (tokens.length < 4) {
                continue;
            }
            long threadId = Long.parseLong(tokens[0]);
            long timestamp = Long.parseLong(tokens[1]);
            long cpuTime = Long.parseLong(tokens[2]);
            long userTime = Long.parseLong(tokens[3]);
            String stackTraceStr = tokens[4];
            StackTraceElement[] stackTrace = StackTraceElement.fromString(stackTraceStr);
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, timestamp, cpuTime, userTime, stackTrace);
            threadSnapshots.add(threadSnapshot);
        }
    }

    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        List<ThreadSnapshot> filteredThreadSnapshots = new ArrayList<>();
        long startTime = timeRange.getStartTime();
        long endTime = timeRange.getEndTime();
        for (ThreadSnapshot threadSnapshot : threadSnapshots) {
            if (threadSnapshot.getTimestamp() >= startTime && threadSnapshot.getTimestamp() <= endTime) {
                filteredThreadSnapshots.add(threadSnapshot);
            }
        }
        timeRange.setThreadSnapshots(filteredThreadSnapshots);
    }

    return threadSnapshots;
}

@Override
public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        return Collections.emptyList();
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
            if (threadSnapshot == null) {
                continue;
            }

            long timestamp = threadSnapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timeRange.contains(timestamp)) {
                    threadSnapshots.add(threadSnapshot);
                    break;
                }
            }
        }
    }

    return threadSnapshots;
}

